{
  "rules": [
    {
      "id": "check_phone_format",
      "description": "Ensure that the phone numbers are in a valid format.",
      "gx_code": "gx.expectations.ExpectColumnValuesToMatchRegex(column='phone', regex='\\d{3}-\\d{3}-\\d{4}')",
      "evidence_references": ["https://en.wikipedia.org/wiki/Telephone_number_formatting"]
    },
    {
      "id": "check_zip_format",
      "description": "Ensure that the zip codes are in a valid format.",
      "gx_code": "gx.expectations.ExpectColumnValuesToMatchRegex(column='zip', regex='\\d{5}(-\\d{4})?')",
      "evidence_references": ["https://en.wikipedia.org/wiki/ZIP_code"]
    },
    {
      "id": "check_state_code",
      "description": "Ensure that the state codes are in a valid format.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeInSet(column='state', value_set=['AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA', 'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY'])",
      "evidence_references": ["https://en.wikipedia.org/wiki/List_of_U.S._state_abbreviations"]
    },
    {
      "id": "check_owner_type",
      "description": "Ensure that the owner types are in a valid set of values.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeInSet(column='owner', value_set=['Public', 'Private', 'Non-Profit'])",
      "evidence_references": ["https://www.healthcare.gov/glossary/owner-type/"]
    }
  ],
  "abstentions": [
    "The 'type' column's values are not clearly defined in the schema or documentation."
  ]
}
